 ('structures_specialisees','Structures spécialisées')
insert into plant_patterns.characters (organ_id,code,group_label,label_fr) values
 ((select id from plant_patterns.organs where code='feuille'),'feuille__phyllotaxie','Phyllotaxie','Phyllotaxie'),
 ((select id from plant_patterns.organs where code='feuille'),'feuille__structure','Structure','Structure'),
 ((select id from plant_patterns.organs where code='feuille'),'feuille__attachement','Attachement','Attachement'),
 ((select id from plant_patterns.organs where code='feuille'),'feuille__texture','Texture','Texture'),
 ((select id from plant_patterns.organs where code='feuille'),'feuille__surface','Surface','Surface'),
 ((select id from plant_patterns.organs where code='feuille'),'feuille__nervation','Nervation','Nervation'),
 ((select id from plant_patterns.organs where code='feuille'),'feuille__familles_botaniques','Familles botaniques','Familles botaniques'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__anatomie_florale','Anatomie florale','Anatomie florale'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__organisation_du_perianthe','Organisation du périanthe','Organisation du périanthe'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__symetrie','Symétrie','Symétrie'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__calice_et_corolle','Calice et corolle','Calice et corolle'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__forme_florale','Forme florale','Forme florale'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__merisie','Mérisie','Mérisie'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__formule_florale_et_grands_clades','Formule florale et grands clades','Formule florale et grands clades'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__duree_et_evolution','Durée et évolution','Durée et évolution'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__androcee','Androcée','Androcée'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__gynecee','Gynécée','Gynécée'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__sexualite','Sexualité','Sexualité'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__inflorescence','Inflorescence','Inflorescence'),
 ((select id from plant_patterns.organs where code='fleur'),'fleur__familles_florales','Familles florales','Familles florales')
insert into plant_patterns.character_states (character_id,code,label_fr,definition_fr,how_fr) values
 ((select id from plant_patterns.characters where code='feuille__phyllotaxie'),'alterne','Alterne','Une seule feuille est insérée à chaque nœud, puis l’insertion change de côté le long de la tige.','Suivre la tige sur plusieurs nœuds. Chercher une feuille par nœud, sans se laisser distraire par la forme du limbe.'),
 ((select id from plant_patterns.characters where code='feuille__phyllotaxie'),'opposee','Opposée','Deux feuilles sont insérées face à face au même nœud.','Repérer une paire, puis confirmer la répétition sur plusieurs nœuds.'),
 ((select id from plant_patterns.characters where code='feuille__phyllotaxie'),'verticillee','Verticillée','Trois feuilles ou plus partent du même nœud.','Vérifier que les feuilles partent réellement du même niveau de la tige.'),
 ((select id from plant_patterns.characters where code='feuille__phyllotaxie'),'decussee','Décussée','Les paires opposées successives sont orientées à angle droit.','Regarder l’axe depuis le sommet pour voir le changement d’orientation.'),
 ((select id from plant_patterns.characters where code='feuille__structure'),'simple','Simple','Le limbe forme une seule unité, même lorsqu’il est lobé.','Chercher le bourgeon axillaire à la base de la feuille, pas à la base des lobes.'),
 ((select id from plant_patterns.characters where code='feuille__structure'),'composee','Composée','Le limbe est divisé en folioles distinctes.','Les folioles ne portent normalement pas de bourgeon axillaire.'),
 ((select id from plant_patterns.characters where code='feuille__structure'),'paripennee','Paripennée','La feuille pennée se termine par une paire de folioles.','Observer l’extrémité complète du rachis et confirmer l’absence de foliole terminale.'),
 ((select id from plant_patterns.characters where code='feuille__structure'),'imparipennee','Imparipennée','Une foliole terminale unique termine le rachis.','Suivre le rachis jusqu’à son extrémité.'),
 ((select id from plant_patterns.characters where code='feuille__attachement'),'petiolee','Pétiolée','Un pétiole relie le limbe à la tige.','Observer la zone exacte entre le limbe et la tige.'),
 ((select id from plant_patterns.characters where code='feuille__attachement'),'sessile','Sessile','Le limbe est attaché directement, sans pétiole visible.','Distinguer une feuille sessile d’une feuille dont le pétiole est simplement très court.'),
 ((select id from plant_patterns.characters where code='feuille__texture'),'succulente_charnue','Succulente / charnue','Le limbe est épais et contient des tissus de réserve d’eau.','Comparer l’épaisseur réelle du limbe; ne pas confondre succulence et simple coriacité.'),
 ((select id from plant_patterns.characters where code='feuille__texture'),'coriace','Coriace','La feuille est ferme et résistante, avec une texture rappelant le cuir.','La feuille peut être coriace sans être charnue.'),
 ((select id from plant_patterns.characters where code='feuille__surface'),'glabre','Glabre','Aucun poil n’est visible sur la surface examinée.','Examiner séparément les deux faces, idéalement avec une loupe.'),
 ((select id from plant_patterns.characters where code='feuille__surface'),'pubescente','Pubescente','La surface porte des poils appelés trichomes.','Comparer densité, longueur, orientation et localisation des poils.'),
 ((select id from plant_patterns.characters where code='feuille__nervation'),'nervation_pennee','Nervation pennée','Une nervure médiane porte des nervures latérales, comme une plume.','Ne pas confondre la nervation pennée avec une feuille composée pennée.'),
 ((select id from plant_patterns.characters where code='feuille__nervation'),'nervation_palmee','Nervation palmée','Plusieurs nervures principales rayonnent depuis la base du limbe.','Repérer le point de départ commun des nervures principales.'),
 ((select id from plant_patterns.characters where code='feuille__nervation'),'nervation_acrodrome','Nervation acrodrome','Plusieurs nervures principales convergent vers l’apex.','Suivre les nervures principales depuis leur base jusqu’au sommet.'),
 ((select id from plant_patterns.characters where code='feuille__familles_botaniques'),'fabaceae','Fabaceae','Chez les Fabaceae, les feuilles composées sont fréquentes, mais ce caractère n’est ni constant ni suffisant à lui seul pour reconnaître la famille.','Comparer le rachis, les folioles, la présence éventuelle de stipules et le type paripenné ou imparipenné. Relier ensuite ces observations aux fleurs et aux fruits.'),
 ((select id from plant_patterns.characters where code='feuille__familles_botaniques'),'melastomataceae','Melastomataceae','Plusieurs Melastomataceae montrent des feuilles opposées et une nervation acrodrome très visible.','Comparer simultanément la disposition opposée, les nervures principales convergentes et la surface du limbe. Aucun caractère isolé ne suffit.'),
 ((select id from plant_patterns.characters where code='fleur__anatomie_florale'),'galerie_generale_des_fleurs','Galerie générale des fleurs','Cette galerie rassemble 86 photographies florales. Une même image est retrouvée dans plusieurs leçons selon les caractères qu’elle montre.','Ouvrir et zoomer chaque image, puis comparer fleur véritable, inflorescence, bractée, corolle, étamines et stade de floraison.'),
 ((select id from plant_patterns.characters where code='fleur__anatomie_florale'),'bractee','Bractée','Feuille modifiée associée à une fleur ou à une inflorescence. Elle peut être verte ou vivement colorée et ne doit pas être confondue avec un pétale.','Chercher les fleurs véritables à l’aisselle ou à l’intérieur de chaque grande pièce colorée.'),
 ((select id from plant_patterns.characters where code='fleur__anatomie_florale'),'spathe_et_spadice','Spathe et spadice','La spathe est une grande bractée entourant ou accompagnant un spadice couvert de nombreuses petites fleurs.','Dans la série 0984–0993, ne pas confondre la grande spathe blanche avec un pétale; zoomer sur les fleurs minuscules du spadice.'),
 ((select id from plant_patterns.characters where code='fleur__anatomie_florale'),'couronne_florale','Couronne florale','Structure annexe formant un anneau ou des appendices entre le périanthe et les organes fertiles.','Comparer la couronne membraneuse de 0859 à la couronne centrale profondément découpée de 1004–1019.'),
 ((select id from plant_patterns.characters where code='fleur__anatomie_florale'),'receptacle','Réceptacle','Extrémité élargie de l’axe floral sur laquelle s’insèrent les pièces de la fleur.','Observer le point commun d’insertion du calice, de la corolle, des étamines et du gynécée.'),
 ((select id from plant_patterns.characters where code='fleur__anatomie_florale'),'pedoncule','Pédoncule','Axe portant une fleur solitaire ou une inflorescence.','Le distinguer du pédicelle, qui porte une fleur individuelle dans une inflorescence.'),
 ((select id from plant_patterns.characters where code='fleur__anatomie_florale'),'pedicelle','Pédicelle','Petit axe portant une fleur individuelle.','Suivre la fleur jusqu’à son point d’attache sur le pédoncule ou l’axe de l’inflorescence.'),
 ((select id from plant_patterns.characters where code='fleur__anatomie_florale'),'calicule_epicalice','Calicule / épicalice','Verticille de pièces ressemblant à des sépales, placé à l’extérieur du calice véritable.','Vérifier la présence de deux séries distinctes sous la corolle.'),
 ((select id from plant_patterns.characters where code='fleur__organisation_du_perianthe'),'dichlamydee','Dichlamydée','Fleur possédant deux enveloppes florales: un calice et une corolle.','Comparer les deux verticilles externes et vérifier que sépales et pétales sont différenciés.'),
 ((select id from plant_patterns.characters where code='fleur__organisation_du_perianthe'),'monochlamydee','Monochlamydée','Fleur possédant une seule enveloppe florale.','Ne pas nommer automatiquement cette enveloppe calice ou corolle si son homologie n’est pas établie.'),
 ((select id from plant_patterns.characters where code='fleur__organisation_du_perianthe'),'achlamydee','Achlamydée','Fleur dépourvue de périanthe: ni calice ni corolle.','Vérifier qu’aucune petite pièce réduite ou écailleuse n’entoure les organes fertiles.'),
 ((select id from plant_patterns.characters where code='fleur__organisation_du_perianthe'),'homochlamydee','Homochlamydée','Les pièces du périanthe sont semblables et sont appelées tépales.','Comparer les verticilles: aucune séparation nette en sépales et pétales ne doit être possible.'),
 ((select id from plant_patterns.characters where code='fleur__organisation_du_perianthe'),'heterochlamydee','Hétérochlamydée','Le périanthe est différencié en calice et corolle.','Distinguer les sépales externes des pétales internes par leur forme, texture ou couleur.'),
 ((select id from plant_patterns.characters where code='fleur__symetrie'),'actinomorphe','Actinomorphe','Fleur présentant plusieurs plans de symétrie. Dans un capitule d’Asteraceae, il faut distinguer la symétrie apparente de l’ensemble de celle des fleurs individuelles.','Regarder la fleur de face et tester plusieurs lignes passant par son centre.'),
 ((select id from plant_patterns.characters where code='fleur__symetrie'),'zygomorphe','Zygomorphe','Fleur présentant un seul plan de symétrie.','Regarder la fleur de face et repérer ses parties supérieure, inférieure et latérales.'),
 ((select id from plant_patterns.characters where code='fleur__calice_et_corolle'),'dialysepale','Dialysépale','Les sépales sont libres les uns des autres.','Suivre chaque sépale jusqu’à sa base pour vérifier l’absence de soudure.'),
 ((select id from plant_patterns.characters where code='fleur__calice_et_corolle'),'gamosepale','Gamosépale','Les sépales sont soudés au moins à leur base.','Repérer le tube ou la coupe formée par le calice, puis ses lobes libres.'),
 ((select id from plant_patterns.characters where code='fleur__calice_et_corolle'),'dialypetale','Dialypétale','Les pétales sont libres les uns des autres.','Suivre chaque pétale jusqu’à son point d’insertion. Une vue de face seule peut être insuffisante.'),
 ((select id from plant_patterns.characters where code='fleur__calice_et_corolle'),'gamopetale','Gamopétale','Les pétales sont soudés au moins à leur base.','Distinguer le tube de la corolle, sa gorge, son limbe et ses lobes. Comparer la vue de face avec une future vue latérale ou arrière.'),
 ((select id from plant_patterns.characters where code='fleur__calice_et_corolle'),'tepales_petaloides','Tépales pétaloïdes','Tépales semblables, voyants et colorés comme des pétales.','Vérifier que les pièces ne sont pas clairement séparables en sépales et pétales.'),
 ((select id from plant_patterns.characters where code='fleur__forme_florale'),'corolle_tubulaire','Corolle tubulaire','Les pétales soudés forment un tube plus ou moins long avant de s’élargir en lobes.','Comparer la longueur du tube, la gorge et l’ouverture terminale dans les séries 0840, 0852, 0896 et 0904.'),
 ((select id from plant_patterns.characters where code='fleur__forme_florale'),'labelle','Labelle','Pièce du périanthe fortement différenciée, souvent utilisée comme plateforme ou guide pour les pollinisateurs.','Sur les Orchidaceae 0890–0892, repérer le labelle distinct des autres tépales.'),
 ((select id from plant_patterns.characters where code='fleur__merisie'),'trimere','Trimère','Les pièces florales sont organisées par trois ou par multiples de trois.','Compter six tépales et distinguer deux verticilles de trois; ce caractère soutient une hypothèse de monocotylédone.'),
 ((select id from plant_patterns.characters where code='fleur__merisie'),'pentamere','Pentamère','Un ou plusieurs verticilles floraux comportent cinq pièces.','Compter les cinq lobes ou cinq pétales sans confondre lobes soudés et pétales libres.'),
 ((select id from plant_patterns.characters where code='fleur__merisie'),'pieces_nombreuses','Pièces nombreuses','Un verticille porte un nombre élevé de pièces, parfois augmenté par la sélection horticole.','Comparer les pièces pétaloïdes nombreuses des fleurs doubles aux étamines indéfinies visibles dans la série 1265–1285.'),
 ((select id from plant_patterns.characters where code='fleur__formule_florale_et_grands_clades'),'lire_une_formule_florale','Lire une formule florale','La formule florale condense l’architecture d’une fleur et aide à comparer les familles. Elle résume un pattern diagnostique, mais doit toujours être contrôlée sur la plante.','Lire de gauche à droite : sexualité, symétrie, périanthe, étamines puis gynécée. Les parenthèses signalent des pièces soudées; + sépare les verticilles; ∞ signifie nombreuses pièces.'),
 ((select id from plant_patterns.characters where code='fleur__formule_florale_et_grands_clades'),'monocotyledones_pattern_frequent','Monocotylédones — pattern fréquent','Les monocotylédones possèdent un seul cotylédon. Leurs fleurs sont souvent trimères, avec des pièces par trois ou multiples de trois; la nervation parallèle est fréquente.','Chercher deux verticilles de trois tépales, puis compter les étamines. Utiliser ce faisceau de caractères comme hypothèse, jamais un seul caractère isolé.'),
 ((select id from plant_patterns.characters where code='fleur__formule_florale_et_grands_clades'),'eudicotyledones_dicotyledones','Eudicotylédones (« dicotylédones »)','Les eudicotylédones forment le grand groupe naturel auquel appartiennent la majorité des plantes traditionnellement appelées dicotylédones. Les fleurs sont souvent tétra- ou pentamères.','Comparer les verticilles par quatre ou cinq, puis vérifier la nervation réticulée et les autres organes. Le mot « dicotylédones » reste utile pour débuter, mais il est plus large et historiquement paraphylétique.'),
 ((select id from plant_patterns.characters where code='fleur__duree_et_evolution'),'sepales_caducs','Sépales caducs','Les sépales tombent précocement, pendant ou peu après l’ouverture de la fleur.','Comparer boutons, fleurs ouvertes et jeunes fruits sur la même plante.'),
 ((select id from plant_patterns.characters where code='fleur__duree_et_evolution'),'calice_persistant','Calice persistant','Le calice reste attaché après la floraison et demeure visible avec le fruit.','Observer la base de plusieurs fruits et rechercher les sépales conservés.'),
 ((select id from plant_patterns.characters where code='fleur__duree_et_evolution'),'sepales_accrescents','Sépales accrescents','Les sépales persistent et continuent de grandir après la floraison.','Comparer leur taille au stade bouton, fleur puis fruit; persistant ne signifie pas nécessairement accrescent.'),
 ((select id from plant_patterns.characters where code='fleur__duree_et_evolution'),'calice_marcescent','Calice marcescent','Le calice se dessèche mais reste attaché pendant un certain temps.','Rechercher des pièces sèches encore présentes sans augmentation notable de taille.'),
 ((select id from plant_patterns.characters where code='fleur__duree_et_evolution'),'petales_caducs','Pétales caducs','Les pétales se détachent pendant ou peu après l’anthèse.','Comparer des fleurs d’âges différents et regarder les pétales tombés sous la plante.'),
 ((select id from plant_patterns.characters where code='fleur__duree_et_evolution'),'corolle_persistante','Corolle persistante','La corolle demeure attachée après la floraison, parfois desséchée autour du jeune fruit.','Vérifier que la corolle reste réellement attachée et ne repose pas simplement sur le fruit.'),
 ((select id from plant_patterns.characters where code='fleur__duree_et_evolution'),'petales_accrescents','Pétales accrescents','Les pétales persistent et augmentent de taille après la floraison.','Documenter plusieurs stades; ce caractère est moins fréquent que l’accrescence du calice.'),
 ((select id from plant_patterns.characters where code='fleur__duree_et_evolution'),'corolle_marcescente','Corolle marcescente','La corolle se dessèche tout en restant attachée temporairement.','Comparer dans une même inflorescence les boutons, fleurs fraîches et corolles sèches encore attachées.'),
 ((select id from plant_patterns.characters where code='fleur__androcee'),'monadelphe','Monadelphe','Les filets des étamines sont réunis en un seul faisceau. Chez de nombreuses Malvaceae, ils forment une colonne staminale autour du style.','Observer la base des filets et distinguer leur soudure de leur simple proximité.'),
 ((select id from plant_patterns.characters where code='fleur__androcee'),'diadelphe','Diadelphe','Les filets des étamines forment deux faisceaux.','Compter les groupes de filets soudés, pas seulement les anthères.'),
 ((select id from plant_patterns.characters where code='fleur__androcee'),'anthere_dorsifixe','Anthère dorsifixe','L’anthère est attachée au filet par sa face dorsale.','Observer précisément le point d’attache entre filet et anthère.'),
 ((select id from plant_patterns.characters where code='fleur__androcee'),'anthere_versatile','Anthère versatile','L’anthère, fixée en un point restreint, peut basculer sur le filet.','Une photo rapprochée de profil est nécessaire pour montrer cette mobilité.'),
 ((select id from plant_patterns.characters where code='fleur__androcee'),'etamines_indefinies','Étamines indéfinies','Les étamines sont très nombreuses et leur nombre n’est pas exprimé par une petite valeur fixe.','Dans 1265–1285, distinguer la masse d’étamines jaunes des pétales clairs et du gynécée central.'),
 ((select id from plant_patterns.characters where code='fleur__androcee'),'etamines_exsertes','Étamines exsertes','Les étamines dépassent nettement hors de la corolle ou du périanthe.','Comparer les étamines légèrement exsertes de 1329–1331 aux longs filets de 1522–1524.'),
 ((select id from plant_patterns.characters where code='fleur__androcee'),'didynames_a_confirmer','Didynames — à confirmer','Quatre étamines organisées en deux longues et deux courtes.','Le caractère doit être confirmé par une vue interne nette; une corolle tubulaire ou une appartenance familiale supposée ne suffit pas.'),
 ((select id from plant_patterns.characters where code='fleur__gynecee'),'gynecee_apocarpe','Gynécée apocarpe','Les carpelles sont libres les uns des autres.','Observer plusieurs unités ovariennes distinctes dans une même fleur.'),
 ((select id from plant_patterns.characters where code='fleur__gynecee'),'gynecee_syncarpe','Gynécée syncarpe','Les carpelles sont soudés en un pistil composé.','La coupe de l’ovaire ou le nombre de styles et stigmates peut aider à interpréter la soudure.'),
 ((select id from plant_patterns.characters where code='fleur__gynecee'),'ovaire_supere','Ovaire supère','Les autres pièces florales s’insèrent sous l’ovaire.','Observer le niveau d’insertion du périanthe et des étamines par rapport à l’ovaire.'),
 ((select id from plant_patterns.characters where code='fleur__gynecee'),'ovaire_infere','Ovaire infère','Les autres pièces florales semblent s’insérer au-dessus de l’ovaire.','Observer la position de l’ovaire sous le point d’insertion apparent du périanthe.'),
 ((select id from plant_patterns.characters where code='fleur__sexualite'),'fleur_bisexuee','Fleur bisexuée','La même fleur possède des étamines fonctionnelles et un gynécée fonctionnel.','Vérifier la présence des deux ensembles fertiles sans conclure uniquement par leur forme.'),
 ((select id from plant_patterns.characters where code='fleur__sexualite'),'fleur_staminee','Fleur staminée','Fleur fonctionnellement mâle, portant des étamines fertiles.','Rechercher les anthères et vérifier si le gynécée est absent ou réduit.'),
 ((select id from plant_patterns.characters where code='fleur__sexualite'),'fleur_pistillee','Fleur pistillée','Fleur fonctionnellement femelle, portant un gynécée fertile.','Rechercher stigmate, style et ovaire; les étamines peuvent être absentes ou réduites.'),
 ((select id from plant_patterns.characters where code='fleur__sexualite'),'plante_monoique','Plante monoïque','Une même plante porte des fleurs mâles et des fleurs femelles distinctes.','Cette observation concerne la plante entière: documenter les deux types de fleurs sur le même individu.'),
 ((select id from plant_patterns.characters where code='fleur__sexualite'),'plante_dioique','Plante dioïque','Les fleurs mâles et femelles sont portées par des individus différents.','Comparer plusieurs individus; une seule fleur ne permet pas de conclure.'),
 ((select id from plant_patterns.characters where code='fleur__inflorescence'),'capitule','Capitule','De nombreuses petites fleurs sessiles sont regroupées sur un réceptacle commun. L’ensemble peut ressembler à une seule grande fleur.','Sur l’Asteraceae 0284, distinguer les fleurs périphériques ligulées des petites fleurs du disque central.'),
 ((select id from plant_patterns.characters where code='fleur__inflorescence'),'grappe','Grappe','Des fleurs pédicellées sont disposées le long d’un axe principal.','Sur 1321–1326, suivre l’axe, distinguer les pédicelles et comparer boutons, fleurs ouvertes et jeunes fruits.'),
 ((select id from plant_patterns.characters where code='fleur__inflorescence'),'epi_floral','Épi floral','Des fleurs sessiles ou presque sessiles s’organisent le long d’un axe allongé.','Comparer les différents stades le long des axes violets de 1141–1200.'),
 ((select id from plant_patterns.characters where code='fleur__inflorescence'),'inflorescence_a_bractees_voyantes','Inflorescence à bractées voyantes','De grandes bractées colorées organisent et protègent l’inflorescence tandis que les fleurs véritables, souvent plus petites, apparaissent entre elles.','Dans les séries 0642–0660, les grandes pièces jaunes ou rouges sont des bractées; chercher les fleurs plus discrètes à leur base.'),
 ((select id from plant_patterns.characters where code='fleur__inflorescence'),'cyathe','Cyathe','Inflorescence très réduite des Euphorbia, ressemblant à une fleur unique et accompagnée ici de grandes bractées rouges.','Dans 0831–0834, chercher au centre les petites unités fertiles; les grandes pièces rouges ne sont pas des pétales.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'asteraceae','Asteraceae','Le capitule regroupe de nombreuses petites fleurs sur un réceptacle commun et donne souvent l’illusion d’une fleur unique.','Sur 0284, comparer les fleurs périphériques ligulées aux fleurs centrales du disque.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'gesneriaceae_a_confirmer','Gesneriaceae — à confirmer','La série 0611–0617 montre une corolle gamopétale tubulaire et des feuilles velues, ensemble compatible avec les Gesneriaceae.','Cette attribution reste à confirmer à partir du nom de la plante ou d’autres caractères.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'heliconiaceae_probable','Heliconiaceae — probable','Les séries 0657 et 0660 montrent une inflorescence organisée par de grandes bractées rouges, compatible avec Heliconia.','Les fleurs véritables sont cachées ou peu visibles; ne pas appeler les grandes bractées des pétales.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'costaceae_probable','Costaceae — probable','Les séries 0675–0680 montrent une inflorescence compacte avec des fleurs zygomorphes et des corolles vieillissantes encore attachées.','Comparer boutons, fleurs ouvertes, corolles marcescentes et jeunes fruits.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'euphorbiaceae_probable','Euphorbiaceae — probable','Les fleurs 0780–0781, attribuées provisoirement à Jatropha, montrent des pétales libres. La série 0831–0834 montre un autre pattern familial: le cyathe des Euphorbia.','Comparer deux architectures très différentes sans chercher une ressemblance superficielle unique.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'malvaceae_probable','Malvaceae — probable','La photo 0784 montre une fleur de type Hibiscus avec une colonne staminale, caractère remarquable chez de nombreuses Malvaceae.','Agrandir la zone centrale pour suivre la colonne formée par les filets soudés.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'araceae_probable','Araceae — probable','La série 0984–0993 montre le couple spathe–spadice caractéristique de nombreuses Araceae.','La grande spathe blanche est une bractée; les fleurs véritables sont les nombreuses petites unités portées par le spadice.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'orchidaceae_probable','Orchidaceae — probable','Les images 0890–0892 montrent une fleur fortement zygomorphe avec un labelle spécialisé.','Comparer le labelle, les autres tépales et la colonne centrale.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'solanaceae_probable','Solanaceae — probable','La photo 0904 est compatible avec Brugmansia: longue corolle gamopétale pendante et cinq lobes.','Cette identification reste probable tant que le nom de la plante ou d’autres caractères ne sont pas documentés.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'rubiaceae_probable','Rubiaceae — probable','La série 0976–0982 montre de petites fleurs actinomorphes à corolle gamopétale, regroupées en inflorescence compacte.','Associer ces fleurs aux feuilles opposées et rechercher les stipules interpétiolaires avant confirmation.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'apocynaceae_probable','Apocynaceae — probable','Les séries 1116–1156 et 1220–1222 montrent une corolle gamopétale pentamère; la seconde série est une forme horticole double qui masque en partie l’architecture ordinaire.','Comparer les cinq lobes, le tube basal, les feuilles opposées et les boutons contortés avant confirmation.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'verbenaceae_probable','Verbenaceae — probable','La série 1141–1200 montre de petites fleurs violettes gamopétales et zygomorphes disposées le long d’épis très allongés.','Comparer les fleurs ouvertes, l’axe floral et les feuilles opposées à marge dentée.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'amaryllidaceae_probable','Amaryllidaceae — probable','Les séries 1178 et 1522–1524 montrent six tépales, une organisation trimère et des feuilles à nervation parallèle.','Comparer la petite fleur en entonnoir de 1178 aux longues pièces étroites et étamines exsertes de 1522–1524.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'calophyllaceae_probable','Calophyllaceae — probable','La série 1265–1285 montre une fleur claire, actinomorphe, portant un très grand nombre d’étamines jaunes.','Le faisceau d’étamines indéfinies est le caractère pédagogique principal; le genre et l’espèce restent à confirmer.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'acanthaceae_probable','Acanthaceae — probable','Les séries 1201–1202 et 1329–1331 montrent des fleurs zygomorphes, souvent tubulaires, avec des organes fertiles visibles ou exserts.','Comparer la corolle, les bractées éventuelles et l’organisation de l’inflorescence avant confirmation.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'bignoniaceae_probable','Bignoniaceae — probable','Les photographies 1344–1345 montrent de grandes fleurs jaunes en trompette, à corolle gamopétale.','La présence d’étamines didynames doit être contrôlée dans une vue interne plus rapprochée.'),
 ((select id from plant_patterns.characters where code='fleur__familles_florales'),'plumbaginaceae_probable','Plumbaginaceae — probable','Les séries 1418–1434 montrent des fleurs bleues actinomorphes à cinq lobes portées en groupes.','Comparer le long tube de la corolle, les cinq lobes et les boutons allongés.')
